function encryptField(plaintext, key, iv) {
  const cipher = crypto.createCipheriv('aes-128-cbc', key, iv);
  return Buffer.concat([cipher.update(plaintext), cipher.final()]);
}

function encryptBackup(data, key) {
  const cipher = forge.cipher.createCipher('AES-CBC', key);
  cipher.start({ iv: forge.random.getBytesSync(16) });
  cipher.update(forge.util.createBuffer(data));
  cipher.finish();
  return cipher.output.getBytes();
}

function legacyDecrypt(ciphertext, key) {
  const bytes = CryptoJS.DES.decrypt(ciphertext, key);
  return bytes.toString(CryptoJS.enc.Utf8);
}

function decryptLegacyExport(payload, key) {
  return CryptoJS.TripleDES.decrypt(payload, key).toString(CryptoJS.enc.Utf8);
}

function obfuscateToken(token, key) {
  return CryptoJS.RC4.encrypt(token, key).toString();
}
